using System.Buffers.Binary;
using System.Globalization;
using System.Security.Cryptography;
using System.Runtime.InteropServices;
using TerraRuntime.Core;
using TerraRuntime.World;

namespace TerraRuntime.Tests;

public sealed class EarlyTerrainReference1458Tests
{
    // Official TerrariaServer 1.4.5.8 Linux executable, SHA-256:
    // 4B87890AC53D40F61DB5F928693A379ACF4CCBD8ED3B47EB32FB096F145DF034.
    // Ordinary AddPasses prefix, fresh per-pass seed; identical Reset beach/jungle/snow
    // inputs and TerrainPass output. No candidate output is used to construct these goldens.
    // Cells are x-major: LE ushort type/wall, LE short frameX/frameY, byte active/liquid/kind.
    // This verifies the cells, ordered pyramid candidates and next RNG, not all GenVars,
    // StructureMap entries, special seeds, or the later full-world geometry.
    [Theory]
    [InlineData(4200, 1200, 1458)]
    [InlineData(4200, 1200, 42)]
    [InlineData(4200, 1200, 8675309)]
    [InlineData(6400, 1800, 1458)]
    [InlineData(6400, 1800, 42)]
    [InlineData(6400, 1800, 8675309)]
    [InlineData(8400, 2400, 1458)]
    [InlineData(8400, 2400, 42)]
    [InlineData(8400, 2400, 8675309)]
    public void Production_prefix_matches_each_official_stage(int width, int height, int seed)
    {
        var request = Request(width, height, seed);
        var builder = new Builder();
        new SourceBackedFinal1458().BuildPlan(in request, builder);
        var workspace = new Workspace(width, height);
        foreach (string name in new[] { "Reset", "Terrain", "TerrainLayers" })
            builder.Get(name).Execute(new Context(request, workspace, new RandomAdapter(seed)));

        string prefix = $"{width}|{seed}|";
        string[] rows = Reference.Split('\n', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries)
            .Where(row => row.StartsWith(prefix, StringComparison.Ordinal)).ToArray();
        Assert.Equal(31, rows.Length);
        foreach (string row in rows)
        {
            string[] values = row.Split('|');
            string stage = values[2];
            var random = new RandomAdapter(seed);
            builder.Get(stage).Execute(new Context(request, workspace, random));
            Assert.True(int.Parse(values[3], CultureInfo.InvariantCulture) == random.Next(), $"{stage}: next RNG");
            Assert.True(values[4] == HashCells(workspace), $"{stage}: full cell hash");
            Assert.Equal(values[5], string.Join(";", workspace.CaptureVanillaPyramidCandidates().Select(p => $"{p.X},{p.Y}")));
            if (stage is "FullDesert" or "MushroomPatches" or "Marble" or "Granite" or "FloatingIslands" or "DirtToMud" or "Silt" or "Shinies" or "Webs" or "Underworld" or "Corruption" or "Lakes" or "Slush")
            {
                using var fullHash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
                var column = new WorldTile[height];
                for (int x = 0; x < width; x++)
                {
                    for (int y = 0; y < height; y++) column[y] = At(workspace, x, y);
                    fullHash.AppendData(MemoryMarshal.AsBytes(column.AsSpan()));
                }
                Assert.Equal(values[6], Convert.ToHexString(fullHash.GetHashAndReset()));
            }
            if (stage == "MushroomPatches")
                Assert.Equal(values[7], string.Join(";", workspace.VanillaMushroomCenters.ToArray().Select(p => $"{p.X},{p.Y}")));
            if (stage == "Tunnels")
                Assert.Equal(values[6], string.Join(",", workspace.VanillaTunnelColumns.ToArray()));
            if (stage == "Lakes")
                Assert.Equal(values[7], string.Join(",", workspace.VanillaLakeColumns.ToArray()));
            if (stage == "GenerateIceBiome")
            {
                Assert.Equal(int.Parse(values[6], CultureInfo.InvariantCulture), workspace.VanillaSnowTop);
                Assert.Equal(int.Parse(values[7], CultureInfo.InvariantCulture), workspace.VanillaSnowBottom);
                byte[] bounds = new byte[height * 8];
                for (int y = 0; y < height; y++)
                {
                    BinaryPrimitives.WriteInt32LittleEndian(bounds.AsSpan(y * 8), workspace.VanillaSnowRows[y].Left);
                    BinaryPrimitives.WriteInt32LittleEndian(bounds.AsSpan(y * 8 + 4), workspace.VanillaSnowRows[y].Right);
                }
                Assert.Equal(values[8], Convert.ToHexString(SHA256.HashData(bounds)));
            }
            if (stage == "Underworld")
            {
                WorldChest[] dressers = workspace.CaptureGeneratedChests();
                Assert.Equal(values[7], string.Join(";", dressers.Select(c => $"{c.SlotId},{c.X},{c.Y}")));
                Assert.All(dressers, chest =>
                {
                    Assert.Empty(chest.Name);
                    Assert.Equal(40, chest.Items.Length);
                    Assert.All(chest.Items, item => Assert.True(item.IsEmpty));
                });
            }
            if (stage == "FloatingIslands")
                Assert.Equal(values[7], string.Join(";", workspace.VanillaSkyIslands.ToArray().Select(p => $"{p.X},{p.Y},{p.Style},{p.IsLake}")));
            if (stage == "MountCaves")
                Assert.Equal(values[6], string.Join(";", workspace.VanillaMountainCaves.ToArray().Select(p => $"{p.X},{p.Y}")));
            if (stage == "Marble")
                Assert.Equal(values[7], string.Join(";", workspace.VanillaMarbleRegions.ToArray()
                    .Select(r => $"{r.X - 8},{r.Y - 8},{r.Width + 16},{r.Height + 16}")));
            if (stage == "Granite")
                Assert.Equal(values[7], string.Join(";", workspace.VanillaGraniteRegions.ToArray()
                    .Select(r => $"{r.X - 8},{r.Y - 8},{r.Width + 16},{r.Height + 16}")));
            if (stage == "FullDesert")
            {
                var region = workspace.VanillaUndergroundDesertRegion!.Value;
                var desert = workspace.VanillaDesertGenerationState!.Value;
                Assert.Equal(values[7], $"{region.X},{region.Y},{region.Width},{region.Height}");
                Assert.Equal(values[8], Rect(desert.Hive));
                Assert.Equal(values[9], Rect(desert.DensityBounds));
                int padding = desert.StructurePadding;
                var area = desert.StructureArea;
                Assert.Equal(values[10], Rect(new(area.X - padding, area.Y - padding, area.Width + padding * 2, area.Height + padding * 2)));
            }
        }
        static string Rect(WorldTileRegion r) => $"{r.X},{r.Y},{r.Width},{r.Height}";
    }

    [Theory]
    [InlineData(false, 1)]
    [InlineData(true, 1)]
    [InlineData(true, 0)]
    public void Grass_seeds_center_from_cardinal_dirt_without_resetting_metadata(bool active, ushort type)
    {
        var (request, workspace, builder) = PrepareIsolated();
        foreach ((int x, int y) in new[] { (399, 150), (401, 150), (400, 149), (400, 151) })
            At(workspace, x, y) = new WorldTile { Type = 0, Flags = WorldTileFlags.Active };
        WorldTile original = new()
        {
            Type = type, Wall = 2, FrameX = 18, FrameY = 36,
            Flags = active ? WorldTileFlags.Active : WorldTileFlags.None,
            LiquidAmount = 80, LiquidKind = WorldLiquidKind.Lava
        };
        At(workspace, 400, 150) = original;

        builder.Get("Grass").Execute(new Context(request, workspace, new GrassRandom()));

        WorldTile actual = At(workspace, 400, 150);
        original.Type = 2;
        original.Flags |= WorldTileFlags.Active;
        Assert.Equal(original, actual);
        Assert.False(At(workspace, 399, 149).IsActive); // diagonal air does not exclude the seed
        Assert.False(At(workspace, 400, 50).IsActive); // second sample lacks cardinal dirt
    }

    [Fact]
    public void Grass_does_not_treat_exposure_or_diagonal_dirt_as_cardinal_enclosure()
    {
        var (request, workspace, builder) = PrepareIsolated();
        for (int x = 399; x <= 401; x++)
        for (int y = 149; y <= 151; y++)
            At(workspace, x, y) = new WorldTile { Type = 0, Flags = WorldTileFlags.Active };
        At(workspace, 399, 150).Flags = WorldTileFlags.None;

        builder.Get("Grass").Execute(new Context(request, workspace, new GrassRandom()));

        Assert.Equal(0, At(workspace, 400, 150).Type);
    }

    [Fact]
    public void Mount_caves_do_not_create_a_mountain_when_surface_scan_finds_no_active_tile()
    {
        var (request, workspace, builder) = PrepareIsolated();
        builder.Get("MountCaves").Execute(new Context(request, workspace, new RandomAdapter(1458)));
        foreach (WorldTile tile in workspace.TileStore.Tiles)
            Assert.False(tile.IsActive);
    }

    [Theory]
    [InlineData(53, false)]
    [InlineData(151, false)]
    [InlineData(274, false)]
    [InlineData(45, true)]
    [InlineData(397, true)]
    [InlineData(0, true)]
    public void Mount_caves_use_the_source_substrate_exclusion(ushort type, bool growsMountain)
    {
        var (request, workspace, builder) = PrepareIsolated();
        for (int x = 0; x < workspace.WidthTiles; x++)
            At(workspace, x, 150) = new WorldTile { Type = type, Flags = WorldTileFlags.Active };

        builder.Get("MountCaves").Execute(new Context(request, workspace, new RandomAdapter(1458)));

        int active = 0;
        foreach (WorldTile tile in workspace.TileStore.Tiles)
            if (tile.IsActive) active++;
        Assert.Equal(growsMountain, active > workspace.WidthTiles);
    }

    private static (WorldGenerationRequest, Workspace, Builder) PrepareIsolated()
    {
        var request = Request(4200, 1200, 1458);
        var builder = new Builder();
        new SourceBackedFinal1458().BuildPlan(in request, builder);
        var workspace = new Workspace(4200, 1200);
        builder.Get("Reset").Execute(new Context(request, workspace, new RandomAdapter(1458)));
        Assert.True(workspace.TrySetLayers(200, 400));
        workspace.SetVanillaTerrainState(new TerrainGenerationState1458(200, 400, 180, 400, 100, 180, 380, 400));
        workspace.SetVanillaLiquidLines(750, 800);
        builder.Get("TerrainLayers").Execute(new Context(request, workspace, new RandomAdapter(1458)));
        return (request, workspace, builder);
    }

    private static WorldGenerationRequest Request(int width, int height, int seed) =>
        new(Provider1458.GeneratorId, "EarlyTerrainReference", (ulong)seed, width, height)
        { SeedText = seed.ToString(CultureInfo.InvariantCulture) };

    private static ref WorldTile At(Workspace workspace, int x, int y) =>
        ref workspace.TileStore.Tiles[workspace.TileStore.GetUncheckedIndex(x, y)];

    private static string HashCells(Workspace workspace)
    {
        using var hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
        byte[] column = new byte[workspace.HeightTiles * 11];
        for (int x = 0; x < workspace.WidthTiles; x++)
        {
            for (int y = 0; y < workspace.HeightTiles; y++)
            {
                WorldTile tile = At(workspace, x, y);
                Span<byte> cell = column.AsSpan(y * 11, 11);
                BinaryPrimitives.WriteUInt16LittleEndian(cell, tile.Type);
                BinaryPrimitives.WriteUInt16LittleEndian(cell[2..], tile.Wall);
                BinaryPrimitives.WriteInt16LittleEndian(cell[4..], tile.FrameX);
                BinaryPrimitives.WriteInt16LittleEndian(cell[6..], tile.FrameY);
                cell[8] = tile.IsActive ? (byte)1 : (byte)0;
                cell[9] = tile.LiquidAmount;
                cell[10] = (byte)tile.LiquidKind;
            }
            hash.AppendData(column);
        }
        return Convert.ToHexString(hash.GetHashAndReset());
    }

    private sealed class Builder : IWorldGenerationPlanBuilder
    {
        private readonly Dictionary<string, IWorldGenerationPass> passes = [];
        public void Add(WorldGenerationPassDescriptor descriptor, IWorldGenerationPass pass) => passes.Add(descriptor.Id.Value, pass);
        public IWorldGenerationPass Get(string name) => passes["terraria:1.4.5.8/" + name];
    }

    private sealed class Context(WorldGenerationRequest request, Workspace workspace, IWorldGenerationVanillaRandom random)
        : IWorldGenerationContext
    {
        public WorldGenerationRequest Request => request;
        public IWorldGenerationWorkspace Workspace => workspace;
        public IWorldGenerationMetadataWorkspace Metadata => workspace;
        public IWorldGenerationRandom Random => throw new NotSupportedException();
        public IWorldGenerationVanillaRandom VanillaRandom => random;
        public CancellationToken CancellationToken => CancellationToken.None;
        public void ReportProgress(double fraction, string? message = null) { }
    }

    private sealed class GrassRandom : IWorldGenerationVanillaRandom
    {
        public int Next() => throw new NotSupportedException();
        public int Next(int maxValue) => throw new NotSupportedException();
        public int Next(int minValue, int maxValue) => minValue == 1 ? 400 : minValue == 5 ? 50 : 150;
        public double NextDouble() => throw new NotSupportedException();
        public void NextBytes(byte[] buffer) => throw new NotSupportedException();
    }

    private sealed class RandomAdapter(int seed) : IWorldGenerationVanillaRandom
    {
        private readonly VanillaUnifiedRandom1458 random = new(seed);
        public int Next() => random.Next();
        public int Next(int maxValue) => random.Next(maxValue);
        public int Next(int minValue, int maxValue) => random.Next(minValue, maxValue);
        public double NextDouble() => random.NextDouble();
        public void NextBytes(byte[] buffer) => random.NextBytes(buffer);
    }

